# Write-once strided store with evict_first to avoid cache pollution
@triton.jit
def kernel(in_ptr, out_ptr, ynumel, xnumel, YBLOCK: tl.constexpr, XBLOCK: tl.constexpr):
    tmp0 = tl.load(in_ptr + (x2 + stride * y3), mask, eviction_policy='evict_last')
    tl.store(out_ptr + (y0 + 3*x2 + 150528*y1), tmp0, mask, eviction_policy='evict_first')

